#!/bin/bash
# NOTE: generated by AI since I needed a quick script... :( sorry to all the ai haters
set -euo pipefail

PROJECT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
BUILD_DIR="$PROJECT_DIR/vendor/coreutils"
INSTALL_DIR="${1:-zig-out/programs}"
# Relative destinations are resolved from the project, even from another cwd.
if [[ "$INSTALL_DIR" != /* ]]; then
    INSTALL_DIR="$PROJECT_DIR/$INSTALL_DIR"
fi
JOBS="${JOBS:-$(nproc)}"

for tool in musl-gcc make readelf; do
    command -v "$tool" >/dev/null || { echo "Missing required tool: $tool" >&2; exit 1; }
done
if [[ ! -f "$BUILD_DIR/bootstrap" ]]; then
    echo "Initialize Coreutils first: git submodule update --init --recursive vendor/coreutils" >&2
    exit 1
fi

# Expose Linux UAPI headers without adding the host's glibc include directory.
HEADER_DIR="$PROJECT_DIR/.zig-cache/coreutils-linux-headers"
mkdir -p "$HEADER_DIR"
for header in linux asm asm-generic; do
    if [[ -d "/usr/include/$header" ]]; then
        ln -sfn "/usr/include/$header" "$HEADER_DIR/$header"
    fi
done
if [[ ! -f "$HEADER_DIR/linux/version.h" ]]; then
    echo "Missing Linux UAPI headers (install linux-api-headers on Arch)." >&2
    exit 1
fi

cd "$BUILD_DIR"
if [[ ! -f configure ]]; then
    echo "Bootstrapping..."
    ./bootstrap
fi

# A stamp ensures existing configurations are updated once with these options.
CONFIG_STAMP="$BUILD_DIR/.lazyos-static-config-v1"
if [[ ! -f Makefile || ! -f "$CONFIG_STAMP" || configure -nt "$CONFIG_STAMP" ]]; then
    echo "Configuring static musl executables..."
    ./configure \
        --prefix=/usr \
        --disable-nls \
        --disable-acl \
        --disable-xattr \
        --disable-libcap \
        --without-gmp \
        CC=musl-gcc \
        CPPFLAGS="-I$HEADER_DIR" \
        CFLAGS="-O2 -fno-pie" \
        LDFLAGS="-static -no-pie"
    touch "$CONFIG_STAMP"
fi

# find and xargs belong to GNU Findutils, not Coreutils.
UTILS=(
    ls cat echo cp mv rm mkdir rmdir
    pwd touch chmod chown ln stat
    wc head tail cut sort uniq tee
    true false yes
    du df date uname
    id whoami env printenv install
)
TARGETS=()
for util in "${UTILS[@]}"; do
    target="$util"
    [[ "$util" != install ]] || target=ginstall
    TARGETS+=("src/$target")
done

echo "Generating required headers..."
# Direct executable targets do not generate Automake's BUILT_SOURCES first.
make -j"$JOBS" -f Makefile -f - lazyos-prepare <<'MAKE'
.PHONY: lazyos-prepare
lazyos-prepare: $(BUILT_SOURCES)
MAKE

echo "Building ${#UTILS[@]} utilities..."
make -j"$JOBS" "${TARGETS[@]}"

# Verify every binary before copying anything into the output directory.
for target in "${TARGETS[@]}"; do
    if readelf -lW "$target" | grep ' INTERP ' >/dev/null; then
        echo "Unexpected dynamic executable: $target" >&2
        exit 1
    fi
    if ! readelf -h "$target" | grep -E 'Type: *EXEC ' >/dev/null; then
        echo "Expected a non-PIE executable: $target" >&2
        exit 1
    fi
done

mkdir -p "$INSTALL_DIR"
for i in "${!UTILS[@]}"; do
    cp -- "${TARGETS[$i]}" "$INSTALL_DIR/${UTILS[$i]}"
    echo "  copied ${UTILS[$i]}"
done

echo "Done: $INSTALL_DIR"
